Found [d3-array/README.md at v3.2.2 · d3/d3-array|https://github.com/d3/d3-array/blob/v3.2.2/README.md#quantile] that is using the same [R-7 method|http://en.wikipedia.org/wiki/Quantile#Quantiles_of_a_population] as numpy does.

Just need to sort the array before calling {{d3.quantile()}}

{noformat}const d3 = require("d3-array");

export function quantile(numbers: number[], p: number) {
    if (!numbers.length) {
        throw new Error("Cannot calculate quantiles for empty array");
    }
    return d3.quantile(
        [...numbers].sort((a, b) => a - b),
        p
    );
}{noformat}

